use vstd::prelude::*;

verus! {

    // Specification: arr is sorted in non‐decreasing order
    spec fn is_sorted(arr: &Vec<i32>) -> bool
        decreases arr.len()
    {
        forall |i: usize, j: usize| i < j && j < arr.len() ==> arr[i] <= arr[j]
    }

    // Binary‐search for the first occurrence of `target` in a sorted array.
    // Returns Some(k) if arr[k] == target and k is the first such index,
    // otherwise returns None.
    fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> (index: Option<usize>)
        requires
            is_sorted(arr),
        ensures
            match index {
                Some(k) =>
                    // in‐bounds, equals target, and no earlier hit
                    k < arr.len() &&
                    arr[k] == target &&
                    forall |i: usize| i < k ==> arr[i] != target,
                None =>
                    // no element equals target
                    forall |i: usize| i < arr.len() ==> arr[i] != target,
            }
    {
        let mut lo: usize = 0;
        let mut hi: usize = arr.len();
        // invariant: target lies between [lo,hi) in the sense that
        //   all i < lo satisfy arr[i] < target,
        //   all j ≥ hi satisfy arr[j] ≥ target.
        while lo < hi
            invariant
                lo <= hi && hi <= arr.len(),
                forall |i: usize| i < lo ==> arr[i] < target,
                forall |j: usize| hi <= j && j < arr.len() ==> arr[j] >= target,
            decreases hi - lo,
        {
            let mid = lo + (hi - lo) / 2;
            if arr[mid] < target {
                // everything ≤ mid is < target, so first ≥ target is to the right
                lo = mid + 1;
            } else {
                // arr[mid] ≥ target, so first ≥ target is at or to the left
                hi = mid;
            }
        }
        // At this point lo == hi is the lower‐bound index: all i<lo have arr[i]<target,
        // all j≥lo have arr[j]≥target.
        if lo < arr.len() && arr[lo] == target {
            Some(lo)
        } else {
            None
        }
    }

}

